effect.shader:
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
bvec4 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec2 u_xlat8;
float u_xlat9;
vec2 u_xlat14;
vec2 u_xlat15;
float u_xlat19;
bool u_xlatb19;
float u_xlat20;
void main()
{
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlat1.x = dot(u_xlat0, u_xlat0);
    u_xlat1.x = inversesqrt(u_xlat1.x);
    u_xlat1.xyz = u_xlat0.xyz * u_xlat1.xxx;
    u_xlat1.xyz = u_xlat1.xyz * vec3(vec3(_brightness, _brightness, _brightness));
    u_xlat1.xyz = log2(abs(u_xlat1.xyz));
    u_xlat1.xyz = u_xlat1.xyz * vec3(0.649999976, 0.649999976, 0.649999976);
    u_xlat1.xyz = exp2(u_xlat1.xyz);
    u_xlat1.xyz = u_xlat1.xyz * vec3(5.0, 5.0, 5.0);
    u_xlat1.xyz = floor(u_xlat1.xyz);
    u_xlat1.xyz = u_xlat1.xyz * vec3(0.200000003, 0.200000003, 0.200000003);
    u_xlat1.xyz = log2(u_xlat1.xyz);
    u_xlat1.xyz = u_xlat1.xyz * vec3(vec3(_intensity, _intensity, _intensity));
    u_xlat1.xyz = exp2(u_xlat1.xyz);
    u_xlat2.xyw = (-vec3(vec3(_outline, _outline, _outline))) * vec3(0.001953125, 0.001953125, 0.001953125) + acScreenNorm.xyy;
    u_xlat3 = texture(inputImg, u_xlat2.xy);
    u_xlat19 = dot(u_xlat3, vec4(0.112500004, 0.221249998, 0.0412499979, 0.25));
    u_xlat2.z = _outline * 0.001953125 + acScreenNorm.x;
    u_xlat2 = texture(inputImg, u_xlat2.zw);
    u_xlat2.x = dot(u_xlat2, vec4(0.112500004, 0.221249998, 0.0412499979, 0.25));
    u_xlat3.xz = (-vec2(vec2(_outline, _outline))) * vec2(0.001953125, 0.001953125) + acScreenNorm.xx;
    u_xlat3.y = acScreenNorm.y;
    u_xlat4 = texture(inputImg, u_xlat3.xy);
    u_xlat8.x = dot(u_xlat4, vec4(0.112500004, 0.221249998, 0.0412499979, 0.25));
    u_xlat3.w = _outline * 0.001953125 + acScreenNorm.y;
    u_xlat3 = texture(inputImg, u_xlat3.zw);
    u_xlat14.x = dot(u_xlat3, vec4(0.112500004, 0.221249998, 0.0412499979, 0.25));
    u_xlat3.x = acScreenNorm.x;
    u_xlat3.yzw = vec3(vec3(_outline, _outline, _outline)) * vec3(0.001953125, 0.001953125, 0.001953125) + acScreenNorm.yxy;
    u_xlat4 = texture(inputImg, u_xlat3.xy);
    u_xlat20 = dot(u_xlat4, vec4(0.112500004, 0.221249998, 0.0412499979, 0.25));
    u_xlat3 = texture(inputImg, u_xlat3.zw);
    u_xlat3.x = dot(u_xlat3, vec4(0.112500004, 0.221249998, 0.0412499979, 0.25));
    u_xlat9 = u_xlat2.x + u_xlat3.x;
    u_xlat9 = u_xlat8.x * 2.0 + u_xlat9;
    u_xlat9 = (-u_xlat19) + u_xlat9;
    u_xlat8.x = (-u_xlat8.x) * 2.0 + u_xlat9;
    u_xlat8.x = (-u_xlat14.x) + u_xlat8.x;
    u_xlat14.x = u_xlat20 * 2.0 + u_xlat14.x;
    u_xlat14.x = u_xlat3.x + u_xlat14.x;
    u_xlat14.x = (-u_xlat19) + u_xlat14.x;
    u_xlat19 = (-u_xlat19) * 2.0 + u_xlat14.x;
    u_xlat19 = (-u_xlat2.x) + u_xlat19;
    u_xlat19 = u_xlat19 * u_xlat19;
    u_xlat19 = u_xlat8.x * u_xlat8.x + u_xlat19;
    u_xlatb19 = 0.0399999991<u_xlat19;
    u_xlat19 = u_xlatb19 ? -1.0 : float(0.0);
    u_xlat1.xyz = u_xlat1.xyz * vec3(_threshold) + vec3(u_xlat19);
    u_xlat19 = u_xlat1.z + u_xlat1.x;
    u_xlat19 = u_xlat19 * 12.8000002;
    u_xlatb19 = u_xlat19<u_xlat1.y;
    u_xlat1.xyz = (bool(u_xlatb19)) ? vec3(0.0, 0.0, 0.0) : u_xlat1.xyz;
    u_xlat1.z = dot(u_xlat1.xyz, vec3(0.212599993, 0.715200007, 0.0722000003));
    u_xlatb2 = lessThan(vec4(0.949999988, 0.75, 0.5, 0.25), u_xlat1.zzzz);
    u_xlat3 = u_xlat1.zzzz * vec4(0.899999976, 0.699999988, 0.5, 0.75);
    u_xlat4.xy = u_xlat1.zz * vec2(0.25, 0.5);
    u_xlat15.xy = (u_xlatb2.w) ? u_xlat3.zw : u_xlat4.xy;
    u_xlat14.xy = (u_xlatb2.z) ? u_xlat3.yx : u_xlat15.xy;
    u_xlat1.w = u_xlat1.z * 0.899999976;
    u_xlat8.xy = (u_xlatb2.y) ? u_xlat1.wz : u_xlat14.xy;
    u_xlat1.xy = (u_xlatb2.x) ? u_xlat1.zz : u_xlat8.xy;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat1.w = u_xlat0.w;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat5 = u_xlat0 * u_xlat5;
        u_xlat3 = u_xlat3 * u_xlat4 + u_xlat5;
        u_xlat0.x = u_xlat4.x * u_xlat3.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat0.x : u_xlat3.w;
        fragColor.xyz = u_xlat3.xyz;
    } else {
        fragColor.xyz = u_xlat1.xyz;
        fragColor.w = u_xlat0.w;
    }
    return;
}
